uploads.forEach { launch(io4) { upload(it) } }   // 5th starts as soon as one suspends

// Actually caps in-flight work:
val semaphore = Semaphore(4)
uploads.forEach { launch(Dispatchers.IO) { semaphore.withPermit { upload(it) } } }

