val mutex = Mutex()

suspend fun safeUpdate() = mutex.withLock {
    repo.update()   // may suspend — allowed inside Mutex
}

// DEADLOCK: Mutex is not reentrant
suspend fun deadlock() = mutex.withLock {
    mutex.withLock { }   // waits forever on itself
}

// synchronized: fine only with no suspension point
val lock = Any()
fun quick() = synchronized(lock) { counter++ }

// Race:
var count = 0
scope.launch { count++ }   // read-modify-write, lost updates

// Better: atomic primitive
val count = AtomicInteger(0)
count.incrementAndGet()

// Better for state: CAS loop, lambda may run more than once
val state = MutableStateFlow(0)
state.update { it + 1 }   // never `state.value = state.value + 1`

// Confinement beats all:
val single = Dispatchers.Default.limitedParallelism(1)
scope.launch(single) { count++ }

val numbers: Flow<Int> = flow {
    println("producer running")
    emit(1); emit(2); emit(3)
}

// No output yet — the builder has not run.

// Each collect runs the whole chain again:
numbers.collect { println(it) }   // producer running, 1 2 3
numbers.collect { println(it) }   // producer running, 1 2 3 again

flow<Int> { for (i in 1..10) emit(i) }
    .map { it * 2 }
