    .onEach { log(it) }
    .onStart { emit(0) }        // Loading-style initial emission
    .scan(0) { acc, x -> acc + x }

// first() cancels upstream after one value:
val current = repo.someFlow.first()

// onCompletion sees the cause but cannot swallow it:
flow.onCompletion { cause -> log("done: $cause") }

// CRASHES: emit from a different coroutine
flow {
    withContext(Dispatchers.IO) { emit(readFile()) }
}

// Correct: flowOn moves only the upstream onto IO
flow { emit(readFile()) }
    .flowOn(Dispatchers.IO)
    .collect { render(it) }   // still on the collector's dispatcher

// MISSES the lambda crash:
flowOf(1, 2).catch { emit(-1) }
    .collect { check(it < 10) }   // throws HERE — downstream

// CATCHES it: the body moves upstream of catch
flowOf(1, 2)
    .onEach { check(it < 10) }
    .catch { emit(-1) }
    .collect()

// Never wrap your own emit — it may be the downstream throwing
flow { try { emit(x) } catch (e: Exception) { emit(fallback) } } // anti-pattern
